/* Larguras de colunas ajustáveis por mouse/toque, guardadas somente neste navegador. */
(()=>{'use strict';const KEY='engefex-table-widths-v1';let widths={};try{widths=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
function bind(){for(let [index,table]of [...document.querySelectorAll('table')].entries()){if(table.dataset.columnsReady)continue;let headers=[...table.querySelectorAll('thead tr:first-child th')];if(!headers.length)continue;table.dataset.columnsReady='1';const key=location.hash+'|'+index+'|'+headers.map(h=>h.textContent.trim()).join('|');let cols=null,values=null;function freeze(saved){if(cols)return;values=saved?.length===headers.length?saved:headers.map(h=>Math.max(48,h.getBoundingClientRect().width));let group=document.createElement('colgroup');cols=values.map(value=>{let col=document.createElement('col');col.style.width=value+'px';group.appendChild(col);return col});table.prepend(group);table.style.tableLayout='fixed';table.classList.add('column-sized');size()}function size(){cols.forEach((col,i)=>col.style.width=values[i]+'px');table.style.width=values.reduce((a,b)=>a+b,0)+'px'}function save(){widths[key]=values;try{localStorage.setItem(KEY,JSON.stringify(widths))}catch{}}
if(Array.isArray(widths[key])&&widths[key].every(n=>Number.isFinite(n)&&n>=48&&n<=1200))freeze(widths[key]);headers.forEach((header,i)=>{let handle=document.createElement('span');handle.className='column-resizer';handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','vertical');handle.setAttribute('aria-label','Ajustar largura de '+(header.textContent.trim()||'ações'));handle.title='Arraste para ajustar a largura; use ← e → pelo teclado';header.appendChild(handle);handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();freeze();values[i]=Math.max(48,Math.min(1200,values[i]+(e.key==='ArrowLeft'?-16:16)));size();save()});handle.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();e.stopPropagation();freeze();let start=e.clientX,initial=values[i];handle.setPointerCapture(e.pointerId);const move=event=>{values[i]=Math.max(48,Math.min(1200,initial+event.clientX-start));size()},end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);save()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)})})}}
window.EngefexTableColumns={bind};if(window.MutationObserver)new MutationObserver(bind).observe(document.body,{childList:true,subtree:true});bind();
})();
